RMdX1.text:
//
//
SYSTem:MESSage "$DC_RunModule_Comment"
//
//
//
//	Turning Laser On
//
SYSTem:MESSage "Turning Laser On."
LAS:POW:SETT $DC_Laser_Power_Setting
LAS:POW:TOL 1.0
LAS On
//
//
//	Turning Zohana On
//
SYSTem:MESSage "Turning Detection Heater On."
DETH:TEMP:TOL 3.0
DETH:TEMP:SETT $Array_Heater_Temperature
DETH On
//
//
//	Turning Oven On
//
SYSTem:MESSage "Setting Oven Temperature."
OVEN:TEMP:TOL $Temperature_Tolerance
OVEN:TEMP:SETT $Oven_Temperature
OVEN On
//
//
//	Initializing Autosampler
//
SYSTem:MESSage "Initializing Autosampler."
STR Initialize
//
//	Filling Polymer Pump
//
SYSTem:MESSage "Loading Waste Tray."
STR:ROB:MOV:LOAD Waste
FLU:POLY:PRES Up 0.34 50
FLU:POLY:PRES Down 0.21 200
SYSTem:MESSage "Filling Polymer Pump"
FLU:POLY:FILL $Poly_Fill_Vol
//
//	Waiting for Oven to Stabilize at Run Temperature
//
SYSTem:MESSage "Waiting for Oven to Stabilize at Run Temperature"
OVEN:SYNC $Oven_Wait_Time
//
//	Waiting for Detection Heater to Stabilize at Run Temperature
//
SYSTem:MESSage "Waiting for Detection Heater to Stabilize at Run Temperature"
DETH:SYNC 1800
//
//	Waiting for Laser to Stabilize at Power Setting
//
SYSTem:MESSage "Waiting for Laser to Stabilize at Power Setting"
LAS:SYNC 600
//
//
//	Filling Array
//
SYSTem:MESSage "Filling Array with Polymer."
FLU:CAP:FILL:THRE 1000
FLU:CAP:FILL $Cap_Fill_Vol
//
//	Rinsing Capillaries
//
SYSTem:MESSage "Rinsing Capillary Tips."
STR:ROB:MOV:LOAD Water
SYST:WAIT 3
//
SYSTem:MESSage "Loading Buffer Tray."
STR:ROB:MOV:LOAD Buffer
SYST:WAIT 3
//
//	Bubble Check
//
SYSTem:MESSage "Testing for Normal Current."
EPS:CURR:LIM $Max_Current
EPS:CURR:ARC:THRE $Current_Stability
EPS:VOLT:SETT 2.0
EPS On
SYST:WAIT 2
EPS:CURR:ARC:SELF $DC_Cap8_EPS_ARC_SELF
EPS Off
//
//	Pre Run
//
SYSTem:MESSage "PreRun"
EPS:VOLT:TOL $Voltage_Tolerance
EPS:VOLT:SETT $PreRun_Voltage
EPS On
EPS:SYNC 10
SYST:WAIT $DC_PreRun_Time
EPS Off
SYST:WAIT 3
//
//
//	Rinse Capillaries
//
SYSTem:MESSage "Rinsing Capillary Tips."
STR:ROB:MOV:LOAD Water
SYST:WAIT 3
//
// Sample injection
//
SYSTem:MESSage "Sample Injection."
STR:ROB:ZOFF $Injection_Depth_Offset
STR:CSO $DC_RS_CSData
STR:ROB:MOV:LOAD $DC_RS_Plate_Type
SYST:WAIT 15
EPS:VOLT:SETT $Injection_Voltage
EPS On
SYST:WAIT $DC_Injection_Time
EPS Off
EPS:VOLT:SETT 0.0
SYST:WAIT 1
STR:ROB:ZOFF 0
//
//	Rinsing Capillaries
//
SYSTem:MESSage "Rinsing Capillary Tips."
STR:ROB:MOV:LOAD Water
SYST:WAIT 3
//
//	Starting Electrophoresis
//
SYSTem:MESSage "Loading Buffer Tray."
STR:ROB:MOV:LOAD Buffer
SYST:WAIT 3
SYSTem:MESSage "Ramping Cycle."
EPS:VOLT:TOL $Voltage_Tolerance
EPS:VOLT:SQRR $Run_Voltage $Voltage_Number_Of_Steps $Voltage_Step_Interval
EPS On
SYST:WAIT $Voltage_Ramp_Wait
EPS:SYNC 10
//
//	Data Delay
//
SYSTem:MESSage "Waiting for Data."
SYST:WAIT $DC_Data_Delay
//
//	CCD beginning data read
//
CAM:SHUT Auto
DAT:SRAT $First_ReadOut_Time $Second_ReadOut_Time
DAT:MODe Binning
SYSTem:MESSage "Starting Data Collection."
DAT:COLL Start
SYST:WAIT $DC_Run_Time
SYSTem:MESSage "Stop Data Collection."
DAT:COLL Stop
EPS Off
EPS:VOLT:SETT 0.0
SYST:WAIT 1
//LAS Off
//DETH Off
//OVEN Off
//
//
//	End Of Module
